# Distinct patient prevalence uses any detected specimen; intensity retains patient x clinical condition units.
summary_one<-function(z){u<-z[,.(strength=if(all(is.na(weight)))NA_real_ else median(weight,na.rm=TRUE),positive=any(weight>0,na.rm=TRUE),eligible=any(eligible),n_specimens=sum(eligible)),by=.(patient_id,clinical_group,dataset)];list(eligible_specimens=sum(z$eligible),eligible_patients=uniqueN(z[eligible==TRUE,patient_id]),positive_specimens=sum(z$weight>0,na.rm=TRUE),positive_patients=uniqueN(u[positive==TRUE,patient_id]),patient_prevalence=if(uniqueN(z[eligible==TRUE,patient_id]))uniqueN(u[positive==TRUE,patient_id])/uniqueN(z[eligible==TRUE,patient_id])else NA_real_,patient_condition_units=sum(u$eligible),specimen_median=qsafe(z$weight,.5),patient_condition_median=qsafe(u$strength,.5),patient_condition_q25=qsafe(u$strength,.25),patient_condition_q75=qsafe(u$strength,.75),patient_condition_min=if(all(is.na(u$strength)))NA_real_ else min(u$strength,na.rm=TRUE),patient_condition_max=if(all(is.na(u$strength)))NA_real_ else max(u$strength,na.rm=TRUE),positive_datasets=uniqueN(u[positive==TRUE,dataset]),eligible_datasets=uniqueN(u[eligible==TRUE,dataset]))}
stratify<-function(z,keys){rbindlist(lapply(c('overall','clinical_group','dataset','dataset_clinical','tumor_only','tumor_dataset'),function(st){
 zz<-copy(z);if(st%in%c('tumor_only','tumor_dataset'))zz<-zz[clinical_group!='Normal'];zz[,stratum:=switch(st,overall='All',clinical_group=clinical_group,dataset=dataset,dataset_clinical=paste(dataset,clinical_group,sep='::'),tumor_only='Tumor',tumor_dataset=dataset)]
 bykeys<-c(keys,'stratum');a<-zz[,.(eligible_specimens=sum(eligible),eligible_patients=uniqueN(patient_id[eligible]),positive_specimens=sum(weight>0,na.rm=TRUE),positive_patients=uniqueN(patient_id[!is.na(weight)&weight>0]),specimen_median=qsafe(weight,.5),positive_datasets=uniqueN(dataset[!is.na(weight)&weight>0]),eligible_datasets=uniqueN(dataset[eligible])),by=bykeys]
 unitkeys<-unique(c(bykeys,'patient_id','clinical_group','dataset'));uu<-zz[,.(strength=qsafe(weight,.5),eligible=any(eligible)),by=unitkeys]
 b<-uu[,.(patient_condition_units=sum(eligible),patient_condition_median=qsafe(strength,.5),patient_condition_q25=qsafe(strength,.25),patient_condition_q75=qsafe(strength,.75),patient_condition_min=if(all(is.na(strength)))NA_real_ else min(strength,na.rm=TRUE),patient_condition_max=if(all(is.na(strength)))NA_real_ else max(strength,na.rm=TRUE)),by=bykeys]
 ans<-merge(a,b,by=bykeys);ans[,`:=`(patient_prevalence=ifelse(eligible_patients>0,positive_patients/eligible_patients,NA_real_),stratification=st)];ans}),fill=TRUE)}

